    @Test
    @DisplayName("EP-01 [EP] new object (valid) | new SeasonSwitch() -> AC and heater off, both timers stopped, room at 70, coolTemp 68, heatTemp 77")
    void tc_EP_01() throws Exception {
        SeasonSwitch s = TestSupport.track(new SeasonSwitch());
        assertFalse(s.ac.isOn);
        assertFalse(s.heater.isOn);
        assertFalse(s.timer.isRunning());
        assertFalse(s.room.timer.isRunning());
        assertEquals(70, s.room.temp);
        assertEquals(68, s.coolTemp);
        assertEquals(77, s.heatTemp);
    }

    @Test
    @DisplayName("EP-02 [EP] state OFF (valid) | new switch; cool() -> prints \"Cooling started. RmTemp=70\"; AC on, heater off, control timer running")
    void tc_EP_02() throws Exception {
        SeasonSwitch s = TestSupport.track(new SeasonSwitch());
        String out = TestSupport.captureOut(s::cool);
        assertEquals(List.of("Cooling started. RmTemp=70"), TestSupport.lines(out));
        assertTrue(s.ac.isOn);
        assertFalse(s.heater.isOn);
        assertTrue(s.timer.isRunning());
    }

